-- ===== 0026_habits_base.sql =====
-- Phase 4a, base: habits profile column, pillar periods, habits, weekly targets per habit, checks and
-- server-only event kinds (spec 3, 6.1 and 6.2; plan decisions 5, 6 and 8).

-- Profile ---------------------------------------------------------------------------------------

alter table public.profiles add column habits_enabled boolean not null default false;

-- Periods ---------------------------------------------------------------------------------------
-- A day is only judged when it falls inside a period. A period with ended_on = started_on - 1
-- (turned on and off the same day) covers no day.

create table public.habit_periods (
  user_id    uuid not null references auth.users on delete cascade,
  started_on date not null,
  ended_on   date check (ended_on is null or ended_on >= started_on - 1),
  primary key (user_id, started_on)
);

alter table public.habit_periods enable row level security;
create policy habit_periods_select_own on public.habit_periods
  for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.habit_periods from anon, authenticated;
revoke select on public.habit_periods from anon;

create function public.profiles_habits_period() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_today date := public.local_today(new.id);
begin
  if new.habits_enabled then
    if tg_op = 'UPDATE' and old.habits_enabled then return null; end if;
    -- Turned back on the day it was turned off: the same period continues.
    update public.habit_periods set ended_on = null
     where user_id = new.id and ended_on = v_today - 1;
    if not found then
      insert into public.habit_periods (user_id, started_on) values (new.id, v_today)
      on conflict (user_id, started_on) do update set ended_on = null;
    end if;
  else
    update public.habit_periods set ended_on = v_today - 1
     where user_id = new.id and ended_on is null;
  end if;
  return null;
end $$;

create trigger profiles_habits_period after insert or update of habits_enabled on public.profiles
  for each row execute function public.profiles_habits_period();

create function public.habits_active_on(p_user uuid, p_day date) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.habit_periods
     where user_id = p_user and started_on <= p_day and (ended_on is null or ended_on >= p_day))
$$;

-- Habits ----------------------------------------------------------------------------------------
-- The id comes from the device (the offline queue stays idempotent). No delete: archiving is an
-- update, and the history stays.

create table public.habits (
  id          uuid primary key,
  user_id     uuid not null references auth.users on delete cascade default auth.uid(),
  name        text not null check (char_length(btrim(name)) between 1 and 40 and name = btrim(name)),
  icon        text not null check (icon ~ '^[a-z][a-z0-9-]{0,31}$'),
  per_week    smallint not null check (per_week between 1 and 7),
  sort        integer not null default 0,
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

alter table public.habits enable row level security;
revoke all on public.habits from anon;
revoke delete, truncate on public.habits from authenticated;

create policy habits_select_own on public.habits
  for select to authenticated using (user_id = auth.uid());
create policy habits_insert_own on public.habits
  for insert to authenticated with check (user_id = auth.uid());
create policy habits_update_own on public.habits
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Weekly targets --------------------------------------------------------------------------------
-- N is frozen per habit and week; Q of a week is the sum of its targets. Clients only read them.

create table public.habit_targets (
  habit_id   uuid not null references public.habits on delete cascade,
  user_id    uuid not null references auth.users on delete cascade,
  week_start date not null,
  target     smallint not null check (target between 0 and 7),
  primary key (habit_id, week_start)
);

alter table public.habit_targets enable row level security;
create policy habit_targets_select_own on public.habit_targets
  for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.habit_targets from anon, authenticated;
revoke select on public.habit_targets from anon;

-- Days left in the person's week, today included: 7 on Monday, 1 on Sunday.
create function public.habit_days_left(p_user uuid) returns smallint
language sql stable security definer set search_path = public as $$
  select (8 - extract(isodow from public.local_today(p_user)))::smallint
$$;

-- The targets a week starts with: N for every active habit created (local date) by its Monday.
-- Rows already there stay; a habit created later in the week got its row from habits_targets_sync.
create function public.freeze_habit_targets(p_user uuid, p_week date) returns void
language sql security definer set search_path = public as $$
  insert into public.habit_targets (habit_id, user_id, week_start, target)
  select h.id, h.user_id, p_week, h.per_week
    from public.habits h
   where h.user_id = p_user and h.archived_at is null
     and (h.created_at at time zone coalesce(
           (select timezone from public.profiles where id = p_user), 'America/Sao_Paulo'))::date <= p_week
  on conflict (habit_id, week_start) do nothing
$$;

-- Security invoker: RLS keeps a client on its own habits, so the count is the owner's.
create function public.habits_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
begin
  if tg_op = 'UPDATE' and (new.user_id <> old.user_id or new.id <> old.id) then
    raise exception 'item_immutable' using errcode = 'P0001';
  end if;

  -- created_at decides which weeks freeze_habit_targets gives the habit: it never changes, and a
  -- client cannot date a habit in the future (app_now() is now() outside the tests).
  if tg_op = 'UPDATE' then
    new.created_at := old.created_at;
  elsif current_user in ('authenticated', 'anon') then
    new.created_at := least(new.created_at, public.app_now());
  end if;

  -- Last write wins: the client's updated_at, capped at now(); an older write is dropped.
  new.updated_at := least(new.updated_at, now());
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return null;
  end if;

  -- A new active habit or a reactivated one. The id is left out of the count, so re-sending a
  -- habit that is already active (an upsert from the queue) is not a 21st.
  if new.archived_at is null and (tg_op = 'INSERT' or old.archived_at is not null) then
    perform pg_advisory_xact_lock(hashtextextended('habits:' || new.user_id::text, 0));
    if (select count(*) from public.habits
         where user_id = new.user_id and archived_at is null and id <> new.id) >= 20 then
      raise exception 'too_many_habits' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;

create trigger habits_guard before insert or update on public.habits
  for each row execute function public.habits_guard();

-- The running week of a habit (spec 3.3). Security definer: clients cannot write habit_targets.
create function public.habits_targets_sync() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_today date := public.local_today(new.user_id);
  v_week  date := public.week_start_of(v_today);
  v_left  smallint := public.habit_days_left(new.user_id);
begin
  if tg_op = 'INSERT' then
    -- Created: the days left in the week, today included.
    if new.archived_at is null then
      insert into public.habit_targets (habit_id, user_id, week_start, target)
      values (new.id, new.user_id, v_week, least(new.per_week, v_left))
      on conflict (habit_id, week_start) do nothing;
    end if;
  elsif old.archived_at is null and new.archived_at is not null then
    -- Archived: the week freezes if nothing did yet, then drops to the checks already made, so
    -- the habit cannot keep the week from 100%.
    insert into public.habit_targets (habit_id, user_id, week_start, target)
    values (new.id, new.user_id, v_week, old.per_week)
    on conflict (habit_id, week_start) do nothing;
    update public.habit_targets t
       set target = least(t.target, (select count(*) from public.habit_checks c
                                      where c.habit_id = new.id and c.day between v_week and v_today))
     where t.habit_id = new.id and t.week_start = v_week;
  elsif old.archived_at is not null and new.archived_at is null then
    -- Reactivated: as if created now, but never below a target the week already had.
    insert into public.habit_targets (habit_id, user_id, week_start, target)
    values (new.id, new.user_id, v_week, least(new.per_week, v_left))
    on conflict (habit_id, week_start) do update
      set target = greatest(habit_targets.target, excluded.target);
  elsif new.archived_at is null and new.per_week <> old.per_week then
    -- A new N counts from next week: the running week keeps the old one.
    insert into public.habit_targets (habit_id, user_id, week_start, target)
    values (new.id, new.user_id, v_week, old.per_week)
    on conflict (habit_id, week_start) do nothing;
  end if;
  return null;
end $$;

create trigger habits_targets_sync after insert or update on public.habits
  for each row execute function public.habits_targets_sync();

-- Checks ----------------------------------------------------------------------------------------

create table public.habit_checks (
  habit_id   uuid not null references public.habits on delete cascade,
  user_id    uuid not null references auth.users on delete cascade default auth.uid(),
  day        date not null,
  created_at timestamptz not null default now(),
  primary key (habit_id, day)
);

alter table public.habit_checks enable row level security;
revoke all on public.habit_checks from anon;
revoke update, truncate on public.habit_checks from authenticated;

create policy habit_checks_select_own on public.habit_checks
  for select to authenticated using (user_id = auth.uid());
create policy habit_checks_insert_own on public.habit_checks
  for insert to authenticated with check (user_id = auth.uid());
create policy habit_checks_delete_own on public.habit_checks
  for delete to authenticated using (user_id = auth.uid());

-- Security invoker: the rules apply only to client roles. Security definer functions (the closing,
-- delete_my_account) and the cascade from auth.users run as the owner and pass untouched. RLS keeps
-- a client on its own rows and habits, so a habit it cannot see reads as archived, and the
-- signed-in person's today is the row owner's today.
create function public.habit_checks_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
declare
  v_today date;
  v_row   public.habit_checks := coalesce(new, old);
begin
  if current_user not in ('authenticated', 'anon') then
    return v_row;
  end if;

  v_today := public.my_local_today();
  if v_row.day not in (v_today - 1, v_today) then
    raise exception 'day_closed' using errcode = 'P0001';
  end if;

  if not exists (select 1 from public.habits
                  where id = v_row.habit_id and user_id = auth.uid() and archived_at is null) then
    raise exception 'habit_archived' using errcode = 'P0001';
  end if;

  -- Unchecking a day stays possible after the pillar was turned off.
  if tg_op = 'INSERT' and not exists (
       select 1 from public.habit_periods
        where user_id = auth.uid() and started_on <= new.day
          and (ended_on is null or ended_on >= new.day)) then
    raise exception 'pillar_off' using errcode = 'P0001';
  end if;

  -- Only the closing marks a check valid (habit_checks.counted, added in 0027).
  if tg_op = 'INSERT' then
    new.counted := null;
    return new;
  end if;
  return v_row;
end $$;

create trigger habit_checks_guard before insert or delete on public.habit_checks
  for each row execute function public.habit_checks_guard();

revoke all on function public.profiles_habits_period(), public.habits_active_on(uuid, date),
  public.habit_days_left(uuid), public.freeze_habit_targets(uuid, date), public.habits_guard(),
  public.habits_targets_sync(), public.habit_checks_guard() from public, anon, authenticated;

-- Server-only event kinds -----------------------------------------------------------------------
-- The closing writes them; the insert policy of activity_events (0007) keeps clients out.

insert into public.event_kinds (pillar, kind, server_only) values
  ('habits', 'habit_check', true),
  ('habits', 'habit_day', true),
  ('habits', 'habit_week_target', true);

-- ===== 0027_habits_close.sql =====
-- Phase 4a, day closing: day D closes at the start of D+2 local (spec 6.4), its valid checks are
-- marked (habit_checks.counted), its snapshot goes to habit_days and the server-only events it earns
-- pay habits XP through award_xp (spec 4, 5.1, 5.2, 6.3; plan decision 7).
-- Then the habits_week streak, the daily safety net and the private habit badges (spec 5.3, 5.4;
-- plan decisions 3, 4 and 20).

-- Closed days -----------------------------------------------------------------------------------
-- xp is what the day paid: its valid checks and the +30. The week bonus is the week's, not the day's.

create table public.habit_days (
  user_id    uuid not null references auth.users on delete cascade,
  day        date not null,
  checks     smallint not null,   -- checks made that day
  valid      smallint not null,   -- valid checks (spec 4)
  xp         integer not null,    -- XP paid for the day (valid checks and the +30)
  closed_at  timestamptz not null default now(),
  primary key (user_id, day)
);

alter table public.habit_days enable row level security;
create policy habit_days_select_own on public.habit_days
  for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.habit_days from anon, authenticated;
revoke select on public.habit_days from anon;

-- Null until the day closes; then whether the check fit under its habit's target for the week.
-- Clients have no update on habit_checks, and habit_checks_guard (0026) clears it on their inserts.
alter table public.habit_checks add column counted boolean;

-- The closing reads a person's checks and targets by day and by week.
create index habit_checks_user_day on public.habit_checks (user_id, day);
create index habit_targets_user_week on public.habit_targets (user_id, week_start);

-- Q of a week: the sum of its frozen targets (spec 4).
create function public.habit_week_q(p_user uuid, p_week date) returns integer
language sql stable security definer set search_path = public as $$
  select coalesce(sum(target), 0)::integer
    from public.habit_targets where user_id = p_user and week_start = p_week
$$;

-- Weekly streak (spec 5.3) ---------------------------------------------------------------------
-- In the mould of close_sleep_weeks (0022). A week is judged once its seven days have closed
-- (week_start + 6 <= local_today - 2, Tuesday morning) and closed days never reopen, so a verdict
-- is final and nothing is ever replayed. On target is the week's habit_week_target paid.
--   on target                              -> +1 (and a shield every 4, at most 2)
--   a day outside a period, missed         -> neutral: nothing changes (the activation week included)
--   Q = 0 (every habit archived), missed   -> neutral too
--   missed with a streak and shield        -> the shield goes, the streak stays
--   otherwise                              -> 0
-- The iron habit run needs no state: achievement_stats reads it from the targets and checks. It
-- ends looking at the badges, so every close does (spec 6.4).

create function public.close_habit_weeks(p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_last   date;
  v_s      public.streaks%rowtype;
  v_week   date;
  v_judged integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('xp:' || p_user::text, 0));
  -- The last week whose seven days have all closed.
  v_last := public.local_today(p_user) - 8;
  insert into public.streaks (user_id, kind) values (p_user, 'habits_week') on conflict do nothing;
  select * into v_s from public.streaks where user_id = p_user and kind = 'habits_week' for update;

  if v_s.last_period is null then
    select public.week_start_of(min(started_on)) into v_week
      from public.habit_periods where user_id = p_user;
  else
    v_week := v_s.last_period + 7;
  end if;

  while v_week is not null and v_week <= v_last loop
    if exists (select 1 from public.xp_ledger
                where user_id = p_user and reason = 'habit_week_target' and week_start = v_week) then
      v_s.current := v_s.current + 1;
      v_s.best := greatest(v_s.best, v_s.current);
      if v_s.current % 4 = 0 then v_s.shields := least(2, v_s.shields + 1); end if;
    elsif exists (select 1 from generate_series(v_week, v_week + 6, interval '1 day') d
                   where not public.habits_active_on(p_user, d::date))
       or public.habit_week_q(p_user, v_week) = 0 then
      null;   -- neutral week
    elsif v_s.current > 0 and v_s.shields > 0 then
      v_s.shields := v_s.shields - 1;
    else
      v_s.current := 0;
    end if;
    v_s.last_period := v_week;
    v_week := v_week + 7;
    v_judged := v_judged + 1;
  end loop;

  if v_judged > 0 then
    update public.streaks
       set current = v_s.current, best = v_s.best, shields = v_s.shields, last_period = v_s.last_period
     where user_id = p_user and kind = 'habits_week';
  end if;
  perform public.evaluate_achievements(p_user);
end $$;

revoke all on function public.close_habit_weeks(uuid) from public, anon, authenticated;

-- Closing ---------------------------------------------------------------------------------------
-- In the mould of close_sleep_nights (0022). Every pending day from the day after the last closed
-- one (or the first period) up to local_today - 2, skipping days outside a period. For each day, in
-- order: the week's targets freeze on its first closed day; the day's checks that still fit under
-- their habit's target are marked counted; each valid check emits habit_check (by habits.sort, then
-- id), the day emits habit_day if it had one, and the week emits habit_week_target on the day C
-- reaches Q. Events are unique by source_ref, so a day never pays twice. Runs as the owner: the
-- server-only events pass RLS, and award_xp pays them.

create function public.close_habit_days(p_user uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_first date;
  v_last  date;
  v_day   date;
  v_week  date;
  v_q     integer;
  v_valid integer;
  r       record;
  n       integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('xp:' || p_user::text, 0));
  select min(started_on) into v_first from public.habit_periods where user_id = p_user;
  if v_first is null then return 0; end if;
  select greatest(v_first, max(day) + 1) into v_first from public.habit_days where user_id = p_user;
  v_last := public.local_today(p_user) - 2;
  -- The running week freezes on the first close that touches it (spec 3.3), with the habits as they
  -- are now, before a late change can reach it.
  perform public.freeze_habit_targets(p_user, public.week_start_of(public.local_today(p_user)));

  for v_day in
    select d::date from generate_series(v_first, v_last, interval '1 day') d
     where not exists (select 1 from public.habit_days x where x.user_id = p_user and x.day = d::date)
     order by 1
  loop
    continue when not public.habits_active_on(p_user, v_day);
    v_week := public.week_start_of(v_day);
    -- Only on the week's first closed day. Its Saturday closes on the next Monday and its Sunday on
    -- the next Tuesday: freezing again then would read next week's habits (one reactivated on that
    -- Monday would raise a Q already settled).
    if not exists (select 1 from public.habit_days x
                    where x.user_id = p_user and x.day >= v_week and x.day < v_day) then
      perform public.freeze_habit_targets(p_user, v_week);
    end if;

    -- One check per habit and day, so the days already closed in the week decide whether it fits.
    -- A habit without a target row that week has no room.
    update public.habit_checks c
       set counted = coalesce((select t.target from public.habit_targets t
                                where t.habit_id = c.habit_id and t.week_start = v_week), 0)
                   > (select count(*) from public.habit_checks p
                       where p.habit_id = c.habit_id and p.day >= v_week and p.day < v_day and p.counted)
     where c.user_id = p_user and c.day = v_day;

    v_valid := 0;
    for r in
      select c.habit_id from public.habit_checks c join public.habits h on h.id = c.habit_id
       where c.user_id = p_user and c.day = v_day and c.counted
       order by h.sort, h.id
    loop
      insert into public.activity_events (user_id, pillar, kind, occurred_on, source_ref)
      values (p_user, 'habits', 'habit_check', v_day,
              'habit:' || r.habit_id::text || ':' || to_char(v_day, 'YYYY-MM-DD'))
      on conflict do nothing;
      v_valid := v_valid + 1;
    end loop;

    if v_valid > 0 then
      insert into public.activity_events (user_id, pillar, kind, occurred_on, source_ref)
      values (p_user, 'habits', 'habit_day', v_day, 'habits:' || to_char(v_day, 'YYYY-MM-DD'))
      on conflict do nothing;
    end if;

    v_q := public.habit_week_q(p_user, v_week);
    if v_q > 0 and (select count(*) from public.habit_checks
                     where user_id = p_user and day between v_week and v_day and counted) >= v_q then
      insert into public.activity_events (user_id, pillar, kind, occurred_on, source_ref)
      values (p_user, 'habits', 'habit_week_target', v_day, 'habits-week:' || to_char(v_week, 'YYYY-MM-DD'))
      on conflict do nothing;
    end if;

    insert into public.habit_days (user_id, day, checks, valid, xp)
    values (p_user, v_day,
            (select count(*) from public.habit_checks where user_id = p_user and day = v_day),
            v_valid,
            (select coalesce(sum(l.amount), 0)
               from public.xp_ledger l join public.activity_events e on e.id = l.event_id
              where e.user_id = p_user and e.pillar = 'habits' and e.kind in ('habit_check', 'habit_day')
                and e.occurred_on = v_day));
    n := n + 1;
  end loop;

  -- Even when no day closed: a week may be due, and the badges are looked at on every close.
  perform public.close_habit_weeks(p_user);
  return n;
end $$;

revoke all on function public.habit_week_q(uuid, date), public.close_habit_days(uuid)
  from public, anon, authenticated;

-- Daily safety net (0030 schedules it) ----------------------------------------------------------
-- In the mould of close_all_sleep_nights (0022). Visits everyone with an open period, or with a
-- closed period whose last week is not judged yet (its days may still be pending too, and that week
-- still has to be judged). Returns how many of them had days pending, so a second run the same day
-- returns 0.

create function public.close_all_habit_days() returns integer
language plpgsql security definer set search_path = public as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select distinct p.user_id from public.habit_periods p
      left join public.streaks s on s.user_id = p.user_id and s.kind = 'habits_week'
     where p.ended_on is null or p.ended_on >= coalesce(s.last_period + 7, p.started_on)
  loop
    if public.close_habit_days(r.user_id) > 0 then n := n + 1; end if;
  end loop;
  return n;
end $$;

revoke all on function public.close_all_habit_days() from public, anon, authenticated;

-- XP per event: the habits branch (spec 5.1, 5.2; plan decision 7) -----------------------------
-- 0022's body with the habits branch added, before Treino's. Habits has its own reasons, so nothing
-- of Treino, Nutrition or Sleep ever counts them. A valid check pays round(600 / P), P = max(Q, 7),
-- with Q read from habit_targets when it is paid; with Q >= 7 the Q-th pays what is left of 600. The
-- checks of a week never pay more than 600 together, even when Q changes mid-week, and an amount of
-- 0 writes no row. Weekly max 960.

create or replace function public.award_xp() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_week   date := public.week_start_of(new.occurred_on);
  v_target smallint;
  v_count  integer;
  v_q      integer;
  v_paid   integer;
  v_amount integer;
begin
  -- One award at a time per user: the counts below decide the amount.
  perform pg_advisory_xact_lock(hashtextextended('xp:' || new.user_id::text, 0));

  if new.pillar = 'nutrition' then
    if new.kind = 'day_on_target' then
      v_target := public.week_target_for(new.user_id, v_week, 'nutrition');
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day';
      if v_count < v_target then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', public.session_xp(v_target, v_count + 1), 'nutrition_day', new.id, v_week);
        if v_count + 1 = v_target then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 150, 'nutrition_week_target', new.id, v_week);
        end if;
      else
        select count(*) into v_count from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day_extra';
        if v_count < 2 then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 25, 'nutrition_day_extra', new.id, v_week);
        end if;
      end if;
    elsif new.kind = 'macros_balanced' then
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_balanced';
      if v_count < 3 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 30, 'nutrition_balanced', new.id, v_week);
      end if;
    elsif new.kind = 'day_logged' then
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'nutrition_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 10, 'nutrition_logged', new.id, v_week);
      end if;
    end if;
    perform public.evaluate_achievements(new.user_id);
    return null;
  end if;

  if new.pillar = 'sleep' then
    if new.kind = 'night_on_target' then
      v_target := public.week_target_for(new.user_id, v_week, 'sleep');
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'sleep_night';
      if v_count < v_target then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'sleep', public.session_xp(v_target, v_count + 1), 'sleep_night', new.id, v_week);
        if v_count + 1 = v_target then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'sleep', 150, 'sleep_week_target', new.id, v_week);
        end if;
      else
        select count(*) into v_count from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason = 'sleep_night_extra';
        if v_count < 2 then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'sleep', 25, 'sleep_night_extra', new.id, v_week);
        end if;
      end if;
    elsif new.kind = 'night_rested' then
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'sleep_rested';
      if v_count < 3 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'sleep', 30, 'sleep_rested', new.id, v_week);
      end if;
    elsif new.kind = 'night_logged' then
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'sleep_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'sleep', 10, 'sleep_logged', new.id, v_week);
      end if;
    end if;
    perform public.evaluate_achievements(new.user_id);
    return null;
  end if;

  if new.pillar = 'habits' then
    if new.kind = 'habit_check' then
      v_q := public.habit_week_q(new.user_id, v_week);
      -- This check's place among the week's valid checks (the closing emits them in order).
      select count(*) into v_count from public.activity_events
       where user_id = new.user_id and pillar = 'habits' and kind = 'habit_check'
         and occurred_on between v_week and v_week + 6;
      select coalesce(sum(amount), 0) into v_paid from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'habit_check';
      v_amount := case when v_q >= 7 and v_count = v_q then 600 - v_paid
                       else least(round(600.0 / greatest(v_q, 7))::integer, 600 - v_paid) end;
      if v_amount > 0 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'habits', v_amount, 'habit_check', new.id, v_week);
      end if;
    elsif new.kind = 'habit_week_target' then
      v_q := public.habit_week_q(new.user_id, v_week);
      v_amount := case when v_q >= 7 then 150 else round(150.0 * v_q / 7)::integer end;
      if v_amount > 0 and not exists (
        select 1 from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason = 'habit_week_target'
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'habits', v_amount, 'habit_week_target', new.id, v_week);
      end if;
    elsif new.kind = 'habit_day' then
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'habit_day' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'habits', 30, 'habit_day', new.id, v_week);
      end if;
    end if;
    perform public.evaluate_achievements(new.user_id);
    return null;
  end if;

  if new.pillar <> 'strength' then return null; end if;

  if new.kind in ('workout_completed', 'training_day') then
    if new.kind = 'workout_completed' then
      -- From the cutover on, the day is paid by its check-in when it closes.
      if new.occurred_on >= public.training_checkin_since() then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      -- A day before the cutover already paid by its check-in pays nothing again.
      if exists (select 1 from public.training_days
                  where user_id = new.user_id and day = new.occurred_on and checked and not legacy) then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      update public.training_days set checked = true, legacy = true
       where user_id = new.user_id and day = new.occurred_on;
    else
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'training_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 10, 'training_logged', new.id, v_week);
      end if;
    end if;

    v_target := public.week_target_for(new.user_id, v_week, 'strength');
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason in ('workout', 'training_day');
    if v_count < v_target then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', public.session_xp(v_target, v_count + 1),
              case when new.kind = 'training_day' then 'training_day' else 'workout' end, new.id, v_week);
      if v_count + 1 = v_target and not exists (
        select 1 from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason in ('week_target', 'training_week_target')
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 150,
                case when new.kind = 'training_day' then 'training_week_target' else 'week_target' end,
                new.id, v_week);
        -- A goal met in a week already judged changes that week's verdict: replay the streak.
        if exists (select 1 from public.streaks
                    where user_id = new.user_id and kind = 'training_week' and last_period >= v_week) then
          perform public.close_weeks(new.user_id, true);
        end if;
      end if;
    else
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason in ('workout_extra', 'training_day_extra');
      if v_count < 2 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 25,
                case when new.kind = 'training_day' then 'training_day_extra' else 'workout_extra' end,
                new.id, v_week);
      end if;
    end if;
  elsif new.kind = 'training_detailed' then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'training_detailed';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'training_detailed', new.id, v_week);
    end if;
  elsif new.kind = 'pr' and new.occurred_on < public.training_checkin_since() then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'pr';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'pr', new.id, v_week);
    end if;
  elsif new.kind = 'weight_logged' and new.occurred_on < public.training_checkin_since() then
    if not exists (
      select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
       where l.user_id = new.user_id and l.reason = 'weight' and e.occurred_on = new.occurred_on
    ) then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 10, 'weight', new.id, v_week);
    end if;
  end if;
  perform public.evaluate_achievements(new.user_id);
  return null;
end $$;

revoke all on function public.award_xp() from public, anon, authenticated;

-- Badges (spec 5.4; plan decisions 3 and 20) ----------------------------------------------------
-- All private: never shown to friends. Mirrored by src/features/gamification/achievements.ts
-- (gamification-catalog.test.ts). The metric check is 0022's with the four habits metrics.

alter table public.achievement_catalog drop constraint achievement_catalog_metric_check;
alter table public.achievement_catalog add constraint achievement_catalog_metric_check check (metric in (
  'workouts', 'prs', 'week_targets', 'best_streak', 'weigh_in_run', 'level', 'early_workouts', 'friends',
  'challenges_won', 'nutrition_logged_days', 'nutrition_on_target_days', 'nutrition_week_targets',
  'nutrition_best_streak', 'protein_best_run', 'sleep_logged_nights', 'sleep_on_target_nights',
  'sleep_week_targets', 'sleep_best_streak', 'sleep_clock_best_run', 'habits_checks', 'habits_week_targets',
  'habits_best_streak', 'habits_iron_best_run'));

insert into public.achievement_catalog (code, metric, threshold, xp, sort, private) values
  ('habits_first_check',   'habits_checks',           1,   50, 500, true),
  ('habits_checks_50',     'habits_checks',          50,  100, 510, true),
  ('habits_checks_200',    'habits_checks',         200,  200, 520, true),
  ('habits_checks_500',    'habits_checks',         500,  300, 530, true),
  ('habits_checks_1000',   'habits_checks',        1000,  500, 540, true),
  ('habits_week_target_1', 'habits_week_targets',     1,   75, 550, true),
  ('habits_streak_4',      'habits_best_streak',      4,  150, 560, true),
  ('habits_streak_12',     'habits_best_streak',     12,  400, 570, true),
  ('habits_streak_26',     'habits_best_streak',     26,  800, 580, true),
  ('habits_iron_8',        'habits_iron_best_run',    8,  200, 590, true);

-- Achievement metrics ---------------------------------------------------------------------------
-- 0022's, with the habits ones. They read only closed days (counted is null until then), the
-- ledger, the streak and the frozen targets.

create or replace function public.achievement_stats(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'workouts', (select count(*) from public.activity_events e
                  where e.user_id = p_user and e.kind = 'workout_completed'
                    and e.occurred_on < public.training_checkin_since()
                    and not exists (select 1 from public.training_days t
                                     where t.user_id = p_user and t.day = e.occurred_on
                                       and t.checked and not t.legacy))
              + (select count(*) from public.training_days where user_id = p_user and checked and not legacy),
    'prs', (select count(*) from public.activity_events where user_id = p_user and kind = 'pr'),
    'week_targets', (select count(*) from public.xp_ledger
                      where user_id = p_user and reason in ('week_target', 'training_week_target')),
    'best_streak', coalesce((select best from public.streaks where user_id = p_user and kind = 'training_week'), 0),
    -- Longest run of consecutive weigh-in days (gaps and islands).
    'weigh_in_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select d - (row_number() over (order by d))::int as grp
            from (select distinct occurred_on as d from public.activity_events
                   where user_id = p_user and kind = 'weight_logged') days
        ) runs group by grp
      ) lengths), 0),
    -- Live sessions only: the app sends the local start hour for those, never for backfills.
    'early_workouts', (select count(*) from public.activity_events
                        where user_id = p_user and kind = 'workout_completed'
                          and jsonb_typeof(payload -> 'hour') = 'number' and (payload ->> 'hour')::numeric < 7),
    'friends', (select count(*) from public.friendships where p_user in (user_a, user_b)),
    'challenges_won', (select count(*) from public.challenge_members where user_id = p_user and won),
    'nutrition_logged_days', (select count(*) from public.nutrition_days
                               where user_id = p_user and not imported and logged),
    'nutrition_on_target_days', (select count(*) from public.nutrition_days
                                  where user_id = p_user and not imported and on_target),
    'nutrition_week_targets', (select count(*) from public.xp_ledger
                                where user_id = p_user and reason = 'nutrition_week_target'),
    'nutrition_best_streak', coalesce((select best from public.streaks
                                        where user_id = p_user and kind = 'nutrition_week'), 0),
    -- Longest run of consecutive closed days with protein at or above the target in force.
    'protein_best_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select day - (row_number() over (order by day))::int as grp
            from public.nutrition_days
           where user_id = p_user and not imported
             and protein_g >= (target ->> 'protein_g')::numeric
        ) runs group by grp
      ) lengths), 0),
    'sleep_logged_nights', (select count(*) from public.sleep_nights where user_id = p_user and logged),
    'sleep_on_target_nights', (select count(*) from public.sleep_nights where user_id = p_user and on_target),
    'sleep_week_targets', (select count(*) from public.xp_ledger
                            where user_id = p_user and reason = 'sleep_week_target'),
    'sleep_best_streak', coalesce((select best from public.streaks
                                    where user_id = p_user and kind = 'sleep_week'), 0),
    -- Longest run of consecutive closed nights, all logged, in bed within 30 minutes of the target.
    -- A night without a log, without a target or outside a period breaks it.
    'sleep_clock_best_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select night - (row_number() over (order by night))::int as grp
            from public.sleep_nights
           where user_id = p_user and logged and bed_diff_min <= 30
        ) runs group by grp
      ) lengths), 0),
    'habits_checks', (select count(*) from public.habit_checks where user_id = p_user and counted),
    'habits_week_targets', (select count(*) from public.xp_ledger
                             where user_id = p_user and reason = 'habit_week_target'),
    'habits_best_streak', coalesce((select best from public.streaks
                                     where user_id = p_user and kind = 'habits_week'), 0),
    -- Longest run of consecutive judged weeks in which one same habit met its own target (> 0).
    -- A week without a target row (the habit did not exist or was archived) breaks it; the week it
    -- was archived counts if the lowered target was met (plan decision 4).
    'habits_iron_best_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select t.habit_id,
                 t.week_start - 7 * (row_number() over (partition by t.habit_id order by t.week_start))::int as grp
            from public.habit_targets t
           where t.user_id = p_user and t.target > 0
             and t.week_start <= public.local_today(p_user) - 8
             and (select count(*) from public.habit_checks c
                   where c.habit_id = t.habit_id and c.day between t.week_start and t.week_start + 6
                     and c.counted) >= t.target
        ) runs group by habit_id, grp
      ) lengths), 0)
  )
$$;

revoke all on function public.achievement_stats(uuid) from public, anon, authenticated;

-- ===== 0028_habits_progress.sql =====
-- Phase 4a, progress: the public card, the owner's habits block, the radar's habits axis and the
-- habit history (spec 5.5, 5.6, 6.4, 11; plan decisions 12 and 15). Bodies copied from their latest
-- versions (0023); only the habits parts are new and no signature changes.

-- Whether a week touched a habits period. A period turned on and off the same day
-- (ended_on = started_on - 1) covers no day and touches nothing.
create function public.habits_week_active(p_user uuid, p_week date) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.habit_periods
     where user_id = p_user and started_on <= p_week + 6
       and (ended_on is null or (ended_on >= p_week and ended_on >= started_on)))
$$;

revoke all on function public.habits_week_active(uuid, date) from public, anon, authenticated;

-- Pillar radar ----------------------------------------------------------------------------------
-- 0023's, with the habits branch: closed and active weeks exactly like sleep's (a week is closed
-- once its Sunday closed at D+2, week_start + 6 <= local_today - 2).

create or replace function public.pillar_consistency(p_user uuid, p_pillar public.pillar, p_offset int) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare
  v_last  date;
  v_first date;
  v_weeks date[];
  v_xp    bigint;
begin
  if p_pillar = 'strength' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
    select least(
      (select public.week_start_of(min(occurred_on)) from public.activity_events where user_id = p_user),
      (select public.week_start_of((created_at at time zone coalesce(timezone, 'America/Sao_Paulo'))::date)
         from public.profiles where id = p_user)
    ) into v_first;
  elsif p_pillar = 'nutrition' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
  elsif p_pillar = 'sleep' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
  elsif p_pillar = 'habits' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
  else
    return null;
  end if;
  v_last := v_last - 28 * p_offset;

  select array_agg(w::date) into v_weeks
    from generate_series(v_last - 21, v_last, interval '7 days') w
   where case when p_pillar = 'strength' then w::date >= v_first
              when p_pillar = 'nutrition' then public.nutrition_week_active(p_user, w::date)
              when p_pillar = 'sleep' then public.sleep_week_active(p_user, w::date)
              else public.habits_week_active(p_user, w::date) end;
  if v_weeks is null then return null; end if;

  select coalesce(sum(amount), 0) into v_xp from public.xp_ledger
   where user_id = p_user and pillar = p_pillar and week_start = any(v_weeks);
  return least(1, round(v_xp::numeric / (960 * cardinality(v_weeks)), 4));
end $$;

revoke all on function public.pillar_consistency(uuid, public.pillar, int) from public, anon, authenticated;

-- Public card -----------------------------------------------------------------------------------
-- 0023's, with habits: week.pillars.habits and 960 more in week.max when the week touched a habits
-- period. The pillar's level and XP come with the others; no habit, icon, check or target.

create or replace function public.progress_card(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_week   date := public.local_week_start(p_user);
  v_total  bigint := public.total_xp(p_user);
  v_target smallint;
  v_streak public.streaks%rowtype;
  v_count  jsonb;
  v_split  jsonb;
begin
  v_target := coalesce(
    (select target from public.weekly_targets where user_id = p_user and pillar = 'strength' and week_start = v_week),
    (select days_per_week from public.profiles where id = p_user), 3);
  select * into v_streak from public.streaks where user_id = p_user and kind = 'training_week';
  select jsonb_build_object(
           'workouts', count(*) filter (where reason in ('workout', 'training_day')),
           'extras', count(*) filter (where reason in ('workout_extra', 'training_day_extra')),
           'prs', count(*) filter (where reason = 'pr'),
           'target_hit', count(*) filter (where reason in ('week_target', 'training_week_target')) > 0),
         jsonb_build_object(
           'strength', coalesce(sum(amount) filter (where pillar = 'strength'), 0),
           'nutrition', coalesce(sum(amount) filter (where pillar = 'nutrition'), 0),
           'sleep', coalesce(sum(amount) filter (where pillar = 'sleep'), 0),
           'habits', coalesce(sum(amount) filter (where pillar = 'habits'), 0),
           'bonus', coalesce(sum(amount) filter (where pillar is null), 0))
    into v_count, v_split
    from public.xp_ledger where user_id = p_user and week_start = v_week;
  return jsonb_build_object(
    'total_xp', v_total,
    'level', public.level_json(v_total),
    'pillars', (
      select coalesce(jsonb_object_agg(p.name, public.level_json(p.xp) || jsonb_build_object('xp', p.xp)), '{}'::jsonb)
        from (select e::text as name,
                     coalesce((select sum(amount) from public.xp_ledger where user_id = p_user and pillar = e), 0)::bigint as xp
                from unnest(enum_range(null::public.pillar)) e) p
       where p.name = 'strength' or p.xp > 0),
    'week', jsonb_build_object(
              'start', v_week, 'xp', public.week_xp(p_user, v_week),
              'max', 960 * (1 + public.nutrition_week_active(p_user, v_week)::int
                                + public.sleep_week_active(p_user, v_week)::int
                                + public.habits_week_active(p_user, v_week)::int),
              'target', v_target, 'pillars', v_split) || v_count,
    'streak', jsonb_build_object('current', coalesce(v_streak.current, 0), 'best', coalesce(v_streak.best, 0),
                                 'shields', coalesce(v_streak.shields, 0)),
    'achievements', coalesce((
      select jsonb_agg(jsonb_build_object('code', u.code, 'unlocked_at', u.unlocked_at) order by u.unlocked_at, u.code)
        from public.user_achievements u join public.achievement_catalog c on c.code = u.code
       where u.user_id = p_user and not c.private), '[]'::jsonb)
  );
end $$;

revoke all on function public.progress_card(uuid) from public, anon, authenticated;

-- The owner's extras ----------------------------------------------------------------------------
-- 0023's, plus the radar's habits axis and the habits block once the pillar was ever turned on:
--   habits.week       q: Q of the running week (its frozen targets); c: its valid checks on closed
--                     days (plan decision 12: the client shows C over every check of the week);
--                     xp: the habits XP the week paid so far
--   habits.streak     the habits_week streak
--   habits.last_week  the last week whose seven days closed, whether its goal was met and the XP its
--                     habit_week_target paid (0 without it, plan decision 15); null before the first
--                     period

create or replace function public.my_progress_extras(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_today  date := public.local_today(p_user);
  v_week   date := public.week_start_of(v_today);
  v_lw     date := public.week_start_of(v_today - 8);
  v_first  date;
  v_streak public.streaks%rowtype;
  v_day    public.nutrition_days%rowtype;
  v_tday   public.training_days%rowtype;
  v_nut    jsonb;
  v_train  jsonb;
  v_sfirst date;
  v_sstrk  public.streaks%rowtype;
  v_night  public.sleep_nights%rowtype;
  v_sleep  jsonb;
  v_hfirst date;
  v_hstrk  public.streaks%rowtype;
  v_habits jsonb;
begin
  select public.week_start_of(min(started_on)) into v_first
    from public.nutrition_periods where user_id = p_user;
  if v_first is not null then
    select * into v_streak from public.streaks where user_id = p_user and kind = 'nutrition_week';
    select * into v_day from public.nutrition_days
     where user_id = p_user and not imported order by day desc limit 1;
    v_nut := jsonb_build_object(
      'target', coalesce(
        (select target from public.weekly_targets where user_id = p_user and pillar = 'nutrition' and week_start = v_week),
        (select nutrition_days_per_week from public.profiles where id = p_user), 5),
      'on_target', (select count(*) from public.nutrition_days
                     where user_id = p_user and not imported and on_target and day between v_week and v_week + 6),
      'logged', (select count(*) from public.nutrition_days
                  where user_id = p_user and not imported and logged and day between v_week and v_week + 6),
      'streak', jsonb_build_object('current', coalesce(v_streak.current, 0), 'best', coalesce(v_streak.best, 0),
                                   'shields', coalesce(v_streak.shields, 0)),
      'confirms_on', v_today + 2,
      'last_closed', case when v_day.day is null then null else jsonb_build_object(
        'day', v_day.day, 'logged', v_day.logged, 'on_target', v_day.on_target, 'balanced', v_day.balanced,
        'xp', coalesce((
          select sum(l.amount) from public.xp_ledger l join public.activity_events e on e.id = l.event_id
           where l.user_id = p_user and e.user_id = p_user and e.pillar = 'nutrition'
             and e.occurred_on = v_day.day), 0)) end,
      'last_week', case when v_lw < v_first then null else jsonb_build_object(
        'start', v_lw,
        'target_hit', exists (select 1 from public.xp_ledger
                               where user_id = p_user and reason = 'nutrition_week_target' and week_start = v_lw)) end);
  end if;

  if exists (select 1 from public.checkins where user_id = p_user) then
    select * into v_tday from public.training_days
     where user_id = p_user and checked and not legacy order by day desc limit 1;
    v_train := jsonb_build_object(
      'confirms_on', v_today + 2,
      'last_closed', case when v_tday.day is null then null else jsonb_build_object(
        'day', v_tday.day, 'detailed', v_tday.detailed,
        'xp', coalesce((
          select sum(l.amount) from public.xp_ledger l join public.activity_events e on e.id = l.event_id
           where l.user_id = p_user and e.user_id = p_user
             and e.kind in ('training_day', 'training_detailed') and e.occurred_on = v_tday.day), 0)) end);
  end if;

  select public.week_start_of(min(started_on)) into v_sfirst
    from public.sleep_periods where user_id = p_user;
  if v_sfirst is not null then
    select * into v_sstrk from public.streaks where user_id = p_user and kind = 'sleep_week';
    select * into v_night from public.sleep_nights where user_id = p_user order by night desc limit 1;
    v_sleep := jsonb_build_object(
      'target', coalesce(
        (select target from public.weekly_targets where user_id = p_user and pillar = 'sleep' and week_start = v_week),
        (select sleep_nights_per_week from public.profiles where id = p_user), 5),
      'on_target', (select count(*) from public.sleep_nights
                     where user_id = p_user and on_target and night between v_week and v_week + 6),
      'logged', (select count(*) from public.sleep_nights
                  where user_id = p_user and logged and night between v_week and v_week + 6),
      'streak', jsonb_build_object('current', coalesce(v_sstrk.current, 0), 'best', coalesce(v_sstrk.best, 0),
                                   'shields', coalesce(v_sstrk.shields, 0)),
      'confirms_on', v_today + 2,
      'last_closed', case when v_night.night is null then null else jsonb_build_object(
        'night', v_night.night, 'logged', v_night.logged, 'on_target', v_night.on_target,
        'rested', v_night.rested,
        'xp', coalesce((
          select sum(l.amount)::int from public.xp_ledger l join public.activity_events e on e.id = l.event_id
           where l.user_id = p_user and e.user_id = p_user and e.pillar = 'sleep'
             and e.source_ref = 'sleep:' || to_char(v_night.night, 'YYYY-MM-DD')
             and l.pillar = 'sleep'), 0)) end,
      'last_week', case when v_lw < v_sfirst then null else jsonb_build_object(
        'start', v_lw,
        'target_hit', exists (select 1 from public.xp_ledger
                               where user_id = p_user and reason = 'sleep_week_target' and week_start = v_lw)) end);
  end if;

  select public.week_start_of(min(started_on)) into v_hfirst
    from public.habit_periods where user_id = p_user;
  if v_hfirst is not null then
    select * into v_hstrk from public.streaks where user_id = p_user and kind = 'habits_week';
    v_habits := jsonb_build_object(
      'week', jsonb_build_object(
        'q', public.habit_week_q(p_user, v_week),
        'c', (select count(*) from public.habit_checks
               where user_id = p_user and counted and day between v_week and v_week + 6),
        'xp', (select coalesce(sum(amount), 0) from public.xp_ledger
                where user_id = p_user and pillar = 'habits' and week_start = v_week)),
      'streak', jsonb_build_object('current', coalesce(v_hstrk.current, 0), 'best', coalesce(v_hstrk.best, 0),
                                   'shields', coalesce(v_hstrk.shields, 0)),
      'last_week', case when v_lw < v_hfirst then null else jsonb_build_object(
        'start', v_lw,
        'target_hit', exists (select 1 from public.xp_ledger
                               where user_id = p_user and reason = 'habit_week_target' and week_start = v_lw),
        'bonus', (select coalesce(sum(amount), 0) from public.xp_ledger
                   where user_id = p_user and reason = 'habit_week_target' and week_start = v_lw)) end);
  end if;

  return jsonb_build_object(
    'achievements', coalesce((
      select jsonb_agg(jsonb_build_object('code', code, 'unlocked_at', unlocked_at) order by unlocked_at, code)
        from public.user_achievements where user_id = p_user), '[]'::jsonb),
    'radar', jsonb_build_object(
      'strength', jsonb_build_object('current', public.pillar_consistency(p_user, 'strength', 0),
                                     'previous', public.pillar_consistency(p_user, 'strength', 1)),
      'nutrition', jsonb_build_object('current', public.pillar_consistency(p_user, 'nutrition', 0),
                                      'previous', public.pillar_consistency(p_user, 'nutrition', 1)),
      'sleep', jsonb_build_object('current', public.pillar_consistency(p_user, 'sleep', 0),
                                  'previous', public.pillar_consistency(p_user, 'sleep', 1)),
      'habits', jsonb_build_object('current', public.pillar_consistency(p_user, 'habits', 0),
                                   'previous', public.pillar_consistency(p_user, 'habits', 1))))
    || case when v_nut is null then '{}'::jsonb else jsonb_build_object('nutrition', v_nut) end
    || case when v_sleep is null then '{}'::jsonb else jsonb_build_object('sleep', v_sleep) end
    || case when v_habits is null then '{}'::jsonb else jsonb_build_object('habits', v_habits) end
    || case when v_train is null then '{}'::jsonb else jsonb_build_object('training', v_train) end;
end $$;

revoke all on function public.my_progress_extras(uuid) from public, anon, authenticated;

-- The owner's answer ----------------------------------------------------------------------------
-- 0023's, freezing the week's habit targets and closing pending habit days (which judges the habits
-- weeks) too.

create or replace function public.get_my_progress() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid   uuid := auth.uid();
  v_today date;
  v_card  jsonb;
begin
  if v_uid is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'no_profile' using errcode = 'P0002';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('xp:' || v_uid::text, 0));
  v_today := public.local_today(v_uid);
  perform public.week_target_for(v_uid, public.week_start_of(v_today), 'strength');
  perform public.week_target_for(v_uid, public.week_start_of(v_today), 'nutrition');
  perform public.week_target_for(v_uid, public.week_start_of(v_today), 'sleep');
  perform public.freeze_habit_targets(v_uid, public.week_start_of(v_today));
  perform public.close_training_days(v_uid);
  perform public.close_weeks(v_uid);
  perform public.close_nutrition_days(v_uid);
  perform public.close_sleep_nights(v_uid);
  perform public.close_habit_days(v_uid);
  perform public.evaluate_achievements(v_uid);
  v_card := public.progress_card(v_uid);
  return v_card || public.my_progress_extras(v_uid) || jsonb_build_object(
    'today', v_today,
    'stats', public.achievement_stats(v_uid) || jsonb_build_object('level', (v_card -> 'level' ->> 'level')::int),
    'week', (v_card -> 'week') || jsonb_build_object('weighed_today', exists (
      select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
       where l.user_id = v_uid and l.reason = 'weight' and e.occurred_on = v_today)));
end $$;

revoke all on function public.get_my_progress() from public, anon;
grant execute on function public.get_my_progress() to authenticated;

-- Habit history (spec 6.4) ----------------------------------------------------------------------
-- The signed-in person's habit days in [p_from, p_to] (62 days at most), after closing the pending
-- ones. In the mould of get_sleep_nights (0023).
--   days     the snapshot of each closed day: checks made, valid ones and the XP the day paid (its
--            valid checks and the +30; the week bonus is the week's)
--   checks   every check in the range; counted is null on the days still open (today, yesterday)
--   targets  the frozen targets of the Monday-start weeks the range touches
--   periods  the habits periods touching the range, so the calendar can paint "outside a period";
--            one turned on and off the same day covers no day and is left out

create function public.get_habit_history(p_from date, p_to date) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'no_profile' using errcode = 'P0002';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from + 1 > 62 then
    raise exception 'invalid_range' using errcode = '22023';
  end if;
  perform public.close_habit_days(v_uid);
  return jsonb_build_object(
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'checks', d.checks, 'valid', d.valid, 'xp', d.xp)
                       order by d.day)
        from public.habit_days d
       where d.user_id = v_uid and d.day between p_from and p_to), '[]'::jsonb),
    'checks', coalesce((
      select jsonb_agg(jsonb_build_object('habit_id', c.habit_id, 'day', c.day, 'counted', c.counted)
                       order by c.day, c.habit_id)
        from public.habit_checks c
       where c.user_id = v_uid and c.day between p_from and p_to), '[]'::jsonb),
    'targets', coalesce((
      select jsonb_agg(jsonb_build_object('habit_id', t.habit_id, 'week_start', t.week_start, 'target', t.target)
                       order by t.week_start, t.habit_id)
        from public.habit_targets t
       where t.user_id = v_uid
         and t.week_start between public.week_start_of(p_from) and public.week_start_of(p_to)), '[]'::jsonb),
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object('started_on', p.started_on, 'ended_on', p.ended_on)
                       order by p.started_on)
        from public.habit_periods p
       where p.user_id = v_uid and p.started_on <= p_to
         and (p.ended_on is null or (p.ended_on >= p_from and p.ended_on >= p.started_on))), '[]'::jsonb));
end $$;

revoke all on function public.get_habit_history(date, date) from public, anon;
grant execute on function public.get_habit_history(date, date) to authenticated;

-- ===== 0029_habits_challenge.sql =====
-- Phase 4a, habits challenge: habit_checks counts the valid checks (habit_checks.counted) each
-- participant made in the period (spec 6.5). Team adds them up, solo needs each person to reach the
-- goal. Creating or joining asks for the pillar on and for the opt-in that shows the other
-- participants that count (and nothing else: no habit names, icons or days). A day closes at the
-- start of D+2, so these challenges close when the challenge's own today is past ends_on + 2, after
-- the participants' pending days are closed.
--
-- The functions below are the latest bodies (all from 0024) with only the habits parts added.
-- create_challenge and join_challenge gain p_share_habits (last, default false): the old signatures
-- are dropped and the grants made again. A client that names its parameters without p_share_habits
-- (the Sleep-era one) keeps working through the default.

-- Tables -------------------------------------------------------------------------------------------

alter table public.challenges drop constraint challenges_template_check;
alter table public.challenges add constraint challenges_template_check
  check (template in ('workouts_count', 'weeks_on_target', 'volume_total', 'nutrition_days_on_target',
                      'checkin_days', 'sleep_nights_on_target', 'habit_checks'));

alter table public.challenge_members add column share_habits boolean not null default false;

-- Progress -----------------------------------------------------------------------------------------
-- habit_checks: checks marked counted inside the period. counted is null until the day closes, and
-- a day outside the person's pillar periods never closes, so only closed, valid checks count.

create or replace function public.challenge_progress(p_challenge uuid, p_user uuid) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare
  c public.challenges%rowtype;
  v numeric;
begin
  select * into c from public.challenges where id = p_challenge;
  if not found then return null; end if;
  if c.template in ('workouts_count', 'checkin_days') then
    select count(*) into v from public.training_days
     where user_id = p_user and checked and day between c.starts_on and c.ends_on;
  elsif c.template = 'weeks_on_target' then
    select count(*) into v from public.xp_ledger
     where user_id = p_user and reason in ('week_target', 'training_week_target')
       and week_start between public.week_start_of(c.starts_on) and c.ends_on;
  elsif c.template = 'nutrition_days_on_target' then
    select count(*) into v from public.nutrition_days
     where user_id = p_user and on_target and not imported and day between c.starts_on and c.ends_on
       and public.nutrition_active_on(p_user, day);
  elsif c.template = 'sleep_nights_on_target' then
    select count(*) into v from public.sleep_nights
     where user_id = p_user and on_target and night between c.starts_on and c.ends_on;
  elsif c.template = 'habit_checks' then
    select count(*) into v from public.habit_checks
     where user_id = p_user and counted and day between c.starts_on and c.ends_on;
  else
    select coalesce(sum(least(greatest((payload ->> 'vol')::numeric, 0), 100000)), 0) into v
      from public.activity_events
     where user_id = p_user and kind = 'workout_completed' and occurred_on between c.starts_on and c.ends_on
       and jsonb_typeof(payload -> 'vol') = 'number';
    v := round(v * (case when (select unit from public.profiles where id = p_user) = 'lb'
                         then 0.45359237 else 1 end) / 1000, 1);
  end if;
  return v;
end $$;

revoke all on function public.challenge_progress(uuid, uuid) from public, anon, authenticated;

-- Creating and joining -----------------------------------------------------------------------------
-- The habits template: team or solo, 7 to 92 days, 2 to 20 people, a goal from 1 to 10 checks a day
-- over the period (solo) or that times the people (team).

drop function public.create_challenge(text, text, text, numeric, date, date, uuid[], boolean, boolean, boolean);

create function public.create_challenge(
  p_template text, p_title text, p_mode text, p_target numeric, p_starts_on date, p_ends_on date,
  p_invitees uuid[], p_share_volume boolean default false, p_share_nutrition boolean default false,
  p_share_sleep boolean default false, p_share_habits boolean default false
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me     uuid := auth.uid();
  v_title  text := btrim(coalesce(p_title, ''));
  v_today  date;
  v_people uuid[];
  v_id     uuid;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_me) then
    raise exception 'no_profile' using errcode = 'P0002';
  end if;
  v_today := public.local_today(v_me);
  select coalesce(array_agg(distinct u), '{}') into v_people
    from unnest(coalesce(p_invitees, '{}'::uuid[])) u where u is not null and u <> v_me;

  -- Same rules as checkChallenge in src/features/social/templates.ts.
  if p_template is null
     or p_template not in ('workouts_count', 'weeks_on_target', 'volume_total', 'nutrition_days_on_target',
                           'checkin_days', 'sleep_nights_on_target', 'habit_checks')
     or p_mode is null or p_mode not in ('team', 'solo')
     or (p_template = 'weeks_on_target' and p_mode <> 'solo')
     or char_length(v_title) not between 1 and 60
     or p_starts_on is null or p_ends_on is null
     or p_ends_on - p_starts_on not between 6 and 91
     or p_starts_on < v_today or p_starts_on > v_today + 30
     or p_target is null or p_target <> trunc(p_target) or p_target < 1
     or (p_template in ('workouts_count', 'checkin_days') and p_target > 500)
     or (p_template = 'volume_total' and p_target > 5000)
     or (p_template = 'weeks_on_target'
         and p_target > (public.week_start_of(p_ends_on) - public.week_start_of(p_starts_on)) / 7 + 1)
     or (p_template = 'nutrition_days_on_target'
         and p_target > (p_ends_on - p_starts_on + 1)
                        * (case when p_mode = 'team' then 1 + cardinality(v_people) else 1 end))
     or (p_template = 'sleep_nights_on_target'
         and p_target > (p_ends_on - p_starts_on + 1)
                        * (case when p_mode = 'team' then 1 + cardinality(v_people) else 1 end))
     or (p_template = 'habit_checks'
         and p_target > 10 * (p_ends_on - p_starts_on + 1)
                        * (case when p_mode = 'team' then 1 + cardinality(v_people) else 1 end))
     or cardinality(v_people) not between 1 and 19 then
    raise exception 'invalid_challenge' using errcode = 'P0001';
  end if;
  if exists (select 1 from unnest(v_people) u where not public.are_friends(v_me, u)) then
    raise exception 'not_friends' using errcode = 'P0001';
  end if;
  if p_template = 'volume_total' and not coalesce(p_share_volume, false) then
    raise exception 'volume_opt_in_required' using errcode = 'P0001';
  end if;
  if p_template = 'nutrition_days_on_target' then
    if not (select nutrition_enabled from public.profiles where id = v_me) then
      raise exception 'nutrition_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_nutrition, false) then
      raise exception 'nutrition_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  if p_template = 'sleep_nights_on_target' then
    if not (select sleep_enabled from public.profiles where id = v_me) then
      raise exception 'sleep_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_sleep, false) then
      raise exception 'sleep_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  if p_template = 'habit_checks' then
    if not (select habits_enabled from public.profiles where id = v_me) then
      raise exception 'habits_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_habits, false) then
      raise exception 'habits_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('challenge-create:' || v_me::text, 0));
  if (select count(*) from public.challenges where created_by = v_me and status = 'active') >= 10 then
    raise exception 'challenge_limit' using errcode = 'P0001';
  end if;

  insert into public.challenges (template, title, mode, target, starts_on, ends_on, created_by)
  values (p_template, v_title, p_mode, p_target, p_starts_on, p_ends_on, v_me)
  returning id into v_id;
  insert into public.challenge_members
    (challenge_id, user_id, invited_by, joined_at, share_volume, share_nutrition, share_sleep,
     share_habits)
  values (v_id, v_me, null, public.app_now(), p_template = 'volume_total', p_template = 'nutrition_days_on_target',
          p_template = 'sleep_nights_on_target', p_template = 'habit_checks');
  insert into public.challenge_members (challenge_id, user_id, invited_by)
  select v_id, u, v_me from unnest(v_people) u;
  return jsonb_build_object('id', v_id);
end $$;

drop function public.join_challenge(uuid, boolean, boolean, boolean);

create function public.join_challenge(
  p_id uuid, p_share_volume boolean default false, p_share_nutrition boolean default false,
  p_share_sleep boolean default false, p_share_habits boolean default false
) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
  v_c  public.challenges%rowtype;
  v_m  public.challenge_members%rowtype;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  select * into v_m from public.challenge_members where challenge_id = p_id and user_id = v_me for update;
  if not found then raise exception 'challenge_not_found' using errcode = 'P0002'; end if;
  select * into v_c from public.challenges where id = p_id;
  if v_c.status <> 'active' or public.challenge_today(v_c.created_by, v_c.timezone) > v_c.ends_on then
    raise exception 'challenge_closed' using errcode = 'P0001';
  end if;
  if v_m.joined_at is not null then return; end if;
  if v_c.template = 'volume_total' and not coalesce(p_share_volume, false) then
    raise exception 'volume_opt_in_required' using errcode = 'P0001';
  end if;
  if v_c.template = 'nutrition_days_on_target' then
    if not coalesce((select nutrition_enabled from public.profiles where id = v_me), false) then
      raise exception 'nutrition_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_nutrition, false) then
      raise exception 'nutrition_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  if v_c.template = 'sleep_nights_on_target' then
    if not coalesce((select sleep_enabled from public.profiles where id = v_me), false) then
      raise exception 'sleep_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_sleep, false) then
      raise exception 'sleep_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  if v_c.template = 'habit_checks' then
    if not coalesce((select habits_enabled from public.profiles where id = v_me), false) then
      raise exception 'habits_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_habits, false) then
      raise exception 'habits_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  update public.challenge_members
     set joined_at = public.app_now(), share_volume = (v_c.template = 'volume_total'),
         share_nutrition = (v_c.template = 'nutrition_days_on_target'),
         share_sleep = (v_c.template = 'sleep_nights_on_target'),
         share_habits = (v_c.template = 'habit_checks')
   where challenge_id = p_id and user_id = v_me;
end $$;

revoke all on function
  public.create_challenge(text, text, text, numeric, date, date, uuid[], boolean, boolean, boolean, boolean),
  public.join_challenge(uuid, boolean, boolean, boolean, boolean)
  from public, anon;
grant execute on function
  public.create_challenge(text, text, text, numeric, date, date, uuid[], boolean, boolean, boolean, boolean),
  public.join_challenge(uuid, boolean, boolean, boolean, boolean)
  to authenticated;

-- Closing ------------------------------------------------------------------------------------------
-- A habits day closes at the start of D+2, so the habits template waits two days past ends_on too.

create or replace function public.challenge_grace(p_template text) returns integer
language sql immutable security definer set search_path = public as $$
  select case when p_template in ('nutrition_days_on_target', 'weeks_on_target', 'workouts_count', 'checkin_days',
                                  'sleep_nights_on_target', 'habit_checks')
              then 2 else 0 end
$$;
revoke all on function public.challenge_grace(text) from public, anon, authenticated;

-- As 0024, and for habits every participant's pending days are closed after the XP locks are taken
-- (close_habit_days takes the same lock again) and before final.

create or replace function public.close_challenge(p_challenge uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  c         public.challenges%rowtype;
  v_members uuid[];
  v_won     boolean;
  v_user    uuid;
  r         record;
begin
  perform pg_advisory_xact_lock(hashtextextended('challenge-close', 0));
  select * into c from public.challenges where id = p_challenge for update;
  if not found or c.status <> 'active'
     or public.challenge_today(c.created_by, c.timezone) <= c.ends_on + public.challenge_grace(c.template) then
    return false;
  end if;
  delete from public.challenge_members where challenge_id = p_challenge and joined_at is null;
  select coalesce(array_agg(user_id order by user_id), '{}') into v_members
    from public.challenge_members where challenge_id = p_challenge;
  if cardinality(v_members) < 2 then
    update public.challenges set status = 'cancelled', closed_at = public.app_now() where id = p_challenge;
    return true;
  end if;
  perform public.lock_users(v_members);
  if c.template = 'nutrition_days_on_target' then
    foreach v_user in array v_members loop
      perform public.close_nutrition_days(v_user);
    end loop;
  end if;
  if c.template in ('weeks_on_target', 'workouts_count', 'checkin_days') then
    foreach v_user in array v_members loop
      perform public.close_training_days(v_user);
    end loop;
  end if;
  if c.template = 'sleep_nights_on_target' then
    foreach v_user in array v_members loop
      perform public.close_sleep_nights(v_user);
    end loop;
  end if;
  if c.template = 'habit_checks' then
    foreach v_user in array v_members loop
      perform public.close_habit_days(v_user);
    end loop;
  end if;
  update public.challenge_members
     set final = coalesce(public.challenge_progress(p_challenge, user_id), 0)
   where challenge_id = p_challenge;
  if c.mode = 'team' then
    select sum(final) >= c.target into v_won from public.challenge_members where challenge_id = p_challenge;
    update public.challenge_members set won = v_won where challenge_id = p_challenge;
  else
    update public.challenge_members set won = (final >= c.target) where challenge_id = p_challenge;
    select bool_or(won) into v_won from public.challenge_members where challenge_id = p_challenge;
  end if;
  update public.challenges
     set status = case when v_won then 'won' else 'lost' end, closed_at = public.app_now()
   where id = p_challenge;
  for r in select user_id from public.challenge_members
            where challenge_id = p_challenge and won order by user_id loop
    perform public.award_bonus_xp(r.user_id, 300, 'challenge:' || p_challenge::text);
    perform public.evaluate_achievements(r.user_id);
  end loop;
  return true;
end $$;

revoke all on function public.close_challenge(uuid) from public, anon, authenticated;

-- ===== 0030_habits_cron.sql =====
-- Phase 4a: daily safety net for habits (spec 6.6). get_my_progress and get_habit_history already
-- close pending days and weeks whenever the app opens; this pays the days, the weekly streak and the
-- badges of people who stay away. Challenges need nothing here: close-challenges already waits for
-- challenge_grace and closes the participants' pending days. It only does something where pg_cron
-- exists (Supabase, once the extension is enabled; see docs/SETUP.md §7). Elsewhere, the PGlite
-- tests included, it is a no-op.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron with schema pg_catalog;
    -- Same job name again updates the schedule instead of adding a second job.
    execute $cron$ select cron.schedule('close-habit-days', '50 6 * * *', 'select public.close_all_habit_days()') $cron$;
  end if;
exception when others then
  raise notice 'close-habit-days not scheduled: %', sqlerrm;
end $$;
